// Package app owns the top-level dependency wiring for the IAM process.
package app

import (
	"encoding/json"
	"errors"
	"io"
	"net/http"
	"time"

	"benchmark.local/iam/internal/config"
	"benchmark.local/iam/internal/domain"
	"benchmark.local/iam/internal/repository"
	"benchmark.local/iam/internal/security"
)

const MaxRequestBodyBytes int64 = 1 << 20

type App struct {
	Config        config.Config
	Clock         domain.Clock
	Users         *repository.UserRepository
	Sessions      *repository.SessionRepository
	Resets        *repository.PasswordResetRepository
	Verifications *repository.EmailVerificationRepository
	Tokens        *security.AccessTokenIssuer
}

type DataEnvelope struct {
	Data any `json:"data"`
}

type ErrorDetails struct {
	Code      string `json:"code"`
	Message   string `json:"message"`
	RequestID string `json:"request_id"`
}

type ErrorEnvelope struct {
	Error ErrorDetails `json:"error"`
}

func New(cfg config.Config) (*App, error) {
	return NewWithClock(cfg, domain.SystemClock{})
}

func NewWithClock(cfg config.Config, clock domain.Clock) (*App, error) {
	if err := cfg.Validate(); err != nil {
		return nil, err
	}
	if clock == nil {
		return nil, domain.Invalid("clock must not be nil")
	}
	tokens, err := security.NewAccessTokenIssuer([]byte(cfg.HMACSecret), cfg.Issuer, cfg.AccessTokenTTL, clock)
	if err != nil {
		return nil, domain.Invalid("access token configuration is invalid")
	}
	return &App{Config: cfg, Clock: clock, Users: repository.NewUserRepository(), Sessions: repository.NewSessionRepository(), Resets: repository.NewPasswordResetRepository(), Verifications: repository.NewEmailVerificationRepository(), Tokens: tokens}, nil
}

func (a *App) Handler() http.Handler {
	mux := http.NewServeMux()
	mux.HandleFunc("POST /v1/register", a.register)
	mux.HandleFunc("POST /v1/login", a.login)
	mux.HandleFunc("POST /v1/token/refresh", a.refresh)
	mux.Handle("GET /v1/me", a.requireAuth(http.HandlerFunc(a.me)))
	mux.Handle("POST /v1/logout", a.requireAuth(http.HandlerFunc(a.logout)))
	mux.Handle("POST /v1/logout-all", a.requireAuth(http.HandlerFunc(a.logoutAll)))
	mux.Handle("GET /v1/sessions", a.requireAuth(http.HandlerFunc(a.sessions)))
	mux.Handle("DELETE /v1/sessions/{sessionID}", a.requireAuth(http.HandlerFunc(a.deleteSession)))
	mux.Handle("POST /v1/password/change", a.requireAuth(http.HandlerFunc(a.changePassword)))
	mux.HandleFunc("POST /v1/password-reset/request", a.passwordResetRequest)
	mux.HandleFunc("POST /v1/password-reset/confirm", a.passwordResetConfirm)
	mux.Handle("POST /v1/email-verification/request", a.requireAuth(http.HandlerFunc(a.emailVerificationRequest)))
	mux.HandleFunc("POST /v1/email-verification/confirm", a.emailVerificationConfirm)
	mux.HandleFunc("GET /healthz", func(w http.ResponseWriter, _ *http.Request) {
		writeData(w, http.StatusOK, map[string]string{"status": "ok"})
	})
	mux.HandleFunc("GET /readyz", func(w http.ResponseWriter, _ *http.Request) {
		writeData(w, http.StatusOK, map[string]string{"status": "ready"})
	})
	return http.HandlerFunc(func(w http.ResponseWriter, r *http.Request) {
		requestID := r.Header.Get("X-Request-ID")
		if requestID == "" {
			if id, err := domain.NewID(); err == nil {
				requestID = string(id)
			} else {
				requestID = "unknown"
			}
		}
		w.Header().Set("X-Request-ID", requestID)
		r.Body = http.MaxBytesReader(w, r.Body, MaxRequestBodyBytes)
		mux.ServeHTTP(w, r)
	})
}
// Package config contains process configuration and its environment loader.
package config

import (
	"errors"
	"os"
	"strconv"
	"strings"
	"time"
)

type Config struct {
	Address    string
	Issuer     string
	HMACSecret string

	AccessTokenTTL  time.Duration
	RefreshTokenTTL time.Duration

	RateLimitRequests int
	RateLimitWindow   time.Duration

	ReadTimeout     time.Duration
	WriteTimeout    time.Duration
	IdleTimeout     time.Duration
	ShutdownTimeout time.Duration
}

// Load reads configuration from the process environment and validates it.
func Load() (Config, error) { return LoadFromEnv(os.Getenv) }

// LoadFromEnv is the injectable form of Load for callers with their own
// environment source.
func LoadFromEnv(getenv func(string) string) (Config, error) {
	if getenv == nil {
		return Config{}, errors.New("config: nil environment lookup")
	}

	c := Config{
		Address:           valueOr(getenv("IAM_ADDR"), ":8080"),
		Issuer:            valueOr(getenv("IAM_ISSUER"), "benchmark.local/iam"),
		HMACSecret:        getenv("IAM_HMAC_SECRET"),
		AccessTokenTTL:    durationOr(getenv("IAM_ACCESS_TOKEN_TTL"), 15*time.Minute),
		RefreshTokenTTL:   durationOr(getenv("IAM_REFRESH_TOKEN_TTL"), 30*24*time.Hour),
		RateLimitRequests: intOr(getenv("IAM_RATE_LIMIT_REQUESTS"), 60),
		RateLimitWindow:   durationOr(getenv("IAM_RATE_LIMIT_WINDOW"), time.Minute),
		ReadTimeout:       durationOr(getenv("IAM_READ_TIMEOUT"), 5*time.Second),
		WriteTimeout:      durationOr(getenv("IAM_WRITE_TIMEOUT"), 10*time.Second),
		IdleTimeout:       durationOr(getenv("IAM_IDLE_TIMEOUT"), 60*time.Second),
		ShutdownTimeout:   durationOr(getenv("IAM_SHUTDOWN_TIMEOUT"), 10*time.Second),
	}
	if err := c.Validate(); err != nil {
		return Config{}, err
	}
	return c, nil
}

func valueOr(value, fallback string) string {
	if value == "" {
		return fallback
	}
	return value
}

func durationOr(value string, fallback time.Duration) time.Duration {
	if value == "" {
		return fallback
	}
	duration, err := time.ParseDuration(value)
	if err != nil {
		return -1
	}
	return duration
}

func intOr(value string, fallback int) int {
	if value == "" {
		return fallback
	}
	n, err := strconv.Atoi(value)
	if err != nil {
		return -1
	}
	return n
}

// Validate checks configurations constructed directly by callers.
func (c Config) Validate() error {
	if len([]byte(c.HMACSecret)) < 32 {
		return errors.New("config: HMAC secret must be at least 32 bytes")
	}
	if strings.TrimSpace(c.Issuer) == "" {
		return errors.New("config: issuer must not be empty")
	}
	if c.Address == "" {
		return errors.New("config: address must not be empty")
	}
	if c.AccessTokenTTL <= 0 || c.RefreshTokenTTL <= 0 {
		return errors.New("config: token TTLs must be greater than zero")
	}
